# File: visualization.py
# Description: Read benchmark timings from data_set.csv and plot runtime curves
#              with respect to input size N for all three test scenarios.

import pandas as pd
import matplotlib.pyplot as plt
import os

# Load benchmark timing dataset generated by testbench_time
df = pd.read_csv("data_set.csv")

# Configure font settings for Matplotlib plots
plt.rcParams["font.sans-serif"] = ["Microsoft YaHei"]
plt.rcParams["axes.unicode_minus"] = False

# Map scenario identifiers to human-readable plot titles
scenarios = {
    "ordered": "Ordered Insert, Ordered Delete",
    "ordered_reverse": "Ordered Insert, Reverse Delete",
    "random": "Random Input"
}

# Map CSV columns to operation names
operations = {
    "insert_seconds": "Insertion Time",
    "delete_seconds": "Deletion Time"
}

# Generate insertion and deletion runtime plots for each scenario
for scenario, scenario_title in scenarios.items():
    data = df[df["scenario"] == scenario]

    for column, operation_title in operations.items():
        plt.figure(figsize=(9, 6))

        # Plot a runtime curve for each search tree implementation
        for tree in data["tree"].unique():
            tree_data = data[data["tree"] == tree].sort_values("n")

            plt.plot(
                tree_data["n"],
                tree_data[column],
                marker="o",
                label=tree
            )

        plt.xlabel("Number of Nodes (N)")
        plt.ylabel("Time (seconds)")
        plt.title(f"{operation_title} - {scenario_title}")
        plt.legend()
        plt.grid(True, linestyle="--", alpha=0.5)
        plt.tight_layout()

        # Save the figure to the visualizations directory
        filename = f"{scenario}_{column}.png"
        os.makedirs("visualizations", exist_ok=True)
        plt.savefig(f"visualizations/{filename}", dpi=300)
        plt.show()
